<script setup lang="ts">
import {Head,Link,router,useForm} from '@inertiajs/vue3';
import {reactive,ref} from 'vue';
import AppLayout from '../../layouts/AppLayout.vue';
import ConfirmDialog from '../../components/ConfirmDialog.vue';
import Pagination from '../../components/Pagination.vue';
import type {PageRows} from '../../types/salesOrder';
import type {OpsParticipant} from '../../types/operations';
const props=defineProps<{rows:PageRows<OpsParticipant>;filters:Record<string,string>;counts:Record<string,number>;canManage:boolean;canCertificates:boolean;canQuotation:boolean}>();
const f=reactive({q:'',tipe:'',tahun:'',bulan:'',tindak:'',...props.filters});
const followups:Record<string,string>={uninvoiced:'Belum dibuatkan invoice',pelatihan:'Sertifikat pelatihan belum dikirim',bnsp:'BNSP belum diterima',expired:'Sertifikat habis ≤90 hari'};
const editing=ref<OpsParticipant|null>(null),form=useForm({catatan_monitoring:''});
const search=()=>router.get('/manage-peserta/monitoring',f);
const exportUrl=()=>'/manage-peserta/monitoring?'+new URLSearchParams({...f,export:'1'}).toString();
</script>
<template><Head title="Monitoring Peserta"/><AppLayout title="Monitoring Peserta"><div class="page-head"><h1>Monitoring Peserta</h1><a :href="exportUrl()">Export Excel</a></div><div class="status-summary"><button v-for="(label,key) in followups" :key="key" :aria-pressed="f.tindak===key" @click="f.tindak=key;search()">{{label}} ({{counts[key]}})</button></div><form class="filters" @submit.prevent="search"><label>Cari<input v-model="f.q" type="search" maxlength="100"/></label><label>Tipe<select v-model="f.tipe"><option value="">Semua</option><option>Pelatihan</option><option>Sertifikasi</option><option>Training &amp; Sertifikasi</option></select></label><label>Tahun<input v-model="f.tahun" type="number" min="1900" max="2200"/></label><label>Bulan<select v-model="f.bulan"><option value="">Semua</option><option v-for="n in 12" :key="n" :value="String(n)">{{n}}</option></select></label><label>Tindak lanjut<select v-model="f.tindak"><option value="">Semua</option><option v-for="(label,key) in followups" :key="key" :value="key">{{label}}</option></select></label><button>Terapkan</button></form><p>{{rows.total}} peserta ? Pelatihan {{counts.Pelatihan}} ? Sertifikasi {{counts.Sertifikasi}} ? Training &amp; Sertifikasi {{counts['Training & Sertifikasi']}}</p><div class="table-wrap"><table><thead><tr><th>Peserta</th><th>Program</th><th>Invoice</th><th>Sertifikat</th><th>Catatan / aksi</th></tr></thead><tbody><tr v-for="x in rows.data" :key="x.id"><td>{{x.nama}}<small>{{x.instansi}} · {{x.jabatan}}<br>{{x.no_wa}} · {{x.email}}</small></td><td>{{x.nomor_program}} · {{x.judul}}<small>{{x.tipe}} · {{x.tgl_mulai}}<br>{{x.lokasi}} · PIC {{x.sales}}</small></td><td>{{x.invoice || 'Uninvoiced'}}<small>{{x.pembayaran}}</small></td><td>{{x.no_sertifikat || 'Belum terbit'}} · {{x.status_kirim || 'belum'}}<small>BNSP {{x.no_sertifikat_bnsp || '—'}} · {{x.hasil || 'belum'}}<br>LSP {{x.sertifikat_lsp}} · Berlaku {{x.sertifikat_berlaku || '—'}}</small></td><td>{{x.catatan_monitoring}}<div class="stack"><Link v-if="canQuotation" :href="`/quotation/${x.id_quotation}`">Lihat Quotation {{x.nomor_quotation}}</Link><Link v-if="canCertificates" :href="`/manage-peserta/${x.id_penjualan}?tab=sertifikat`">Kelola Sertifikat</Link><button v-if="canManage" @click="editing=x;form.catatan_monitoring=x.catatan_monitoring || '';form.clearErrors()">Catatan</button></div></td></tr><tr v-if="!rows.data.length"><td colspan="5" class="empty">Tidak ada peserta sesuai filter.</td></tr></tbody></table></div><Pagination :page="rows" label="Halaman Monitoring Peserta"/><ConfirmDialog v-if="editing" title="Catatan monitoring" :busy="form.processing" @cancel="editing=null" @confirm="form.post(`/manage-peserta/peserta/${editing.id}/catatan`,{onSuccess:()=>editing=null})"><label>Catatan {{editing.nama}}<textarea v-model="form.catatan_monitoring" maxlength="500"/></label><p v-for="e in form.errors" :key="e" class="error" role="alert">{{e}}</p></ConfirmDialog></AppLayout></template>
